function publicTools() {
  return TOOLS.map(({ name, description, inputSchema }) => ({ name, description, inputSchema }));
}

function baseUrl() {
  const env = process.env.MCP_BASE_URL;
  if (env && String(env).trim()) return String(env).trim().replace(/\/$/, "");
  return String(DEFAULT_BASE_URL || "").replace(/\/$/, "");
}

function applyPath(pathTpl, args) {
  const used = new Set();
  const path = String(pathTpl).replace(/\{([^}]+)\}/g, (_, k) => {
    used.add(k);
    const v = args[k];
    return encodeURIComponent(v == null ? "" : String(v));
  });
  return { path, used };
}

async function invokeHttp(tool, args) {
  const root = baseUrl();
  if (!root) {
    return { ok: false, error: "missing_base_url", hint: "set MCP_BASE_URL or generate --base-url" };
  }
  const a = args && typeof args === "object" ? args : {};
  const { path, used } = applyPath(tool.http.path, a);
  const method = String(tool.http.method || "GET").toUpperCase();
  const pathParamSet = new Set([...(tool.http.pathParams || []), ...used]);
  let url = root + path;
  const isBodyMethod = method === "POST" || method === "PUT" || method === "PATCH";
  if (!isBodyMethod) {
    const q = new URLSearchParams();
    for (const [k, v] of Object.entries(a)) {
      if (pathParamSet.has(k)) continue;
      if (v === undefined || v === null) continue;
      q.set(k, String(v));
    }
    const qs = q.toString();
    if (qs) url += "?" + qs;
  }
  const headers = {};
  let body;
  if (isBodyMethod) {
    const payload = {};
    for (const [k, v] of Object.entries(a)) {
      if (pathParamSet.has(k)) continue;
      payload[k] = v;
    }
    body = JSON.stringify(payload);
    headers["content-type"] = "application/json";
  }
  try {
    const res = await fetch(url, { method, headers, body });
    const text = await res.text();
    let parsed = text;
    if (text) {
      try { parsed = JSON.parse(text); } catch { parsed = text; }
    } else {
      parsed = null;
    }
    return { ok: res.ok, status: res.status, body: parsed };
  } catch (err) {
    return { ok: false, error: "fetch_failed", message: String(err && err.message ? err.message : err) };
  }
}

function rpcResult(id, result) {
  return { jsonrpc: "2.0", id: id ?? null, result };
}
function rpcError(id, code, message) {
  return { jsonrpc: "2.0", id: id ?? null, error: { code, message } };
}

async function handleRpc(msg) {
  const id = Object.prototype.hasOwnProperty.call(msg, "id") ? msg.id : undefined;
  const method = msg.method || msg.op;
  const isNotification = id === undefined;
  if (!method) return isNotification ? null : rpcError(id, -32600, "missing_method");
  if (method === "notifications/initialized" || method === "initialized" || String(method).startsWith("notifications/")) {
    return null;
  }
  if (method === "initialize") {
    return rpcResult(id ?? null, {
      protocolVersion: "2024-11-05",
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: SERVER_NAME, version: VERSION },
    });
  }
  if (method === "tools/list" || method === "list") {
    return rpcResult(id ?? null, { tools: publicTools() });
  }
  if (method === "tools/call" || method === "call") {
    const params = msg.params || msg;
    const name = params.name || params.tool;
    const args = params.arguments ?? params.args ?? {};
    if (!name) return rpcError(id ?? null, -32602, "missing_tool_name");
    const tool = TOOLS.find((t) => t.name === name);
    if (!tool) {
      const result = { ok: false, error: "unknown_tool:" + name };
      return rpcResult(id ?? null, { ok: false, tool: name, result });
    }
    const result = await invokeHttp(tool, args);
    const statusOk = result.ok !== false;
    return rpcResult(id ?? null, { ok: statusOk, tool: name, result });
  }
  if (method === "ping") {
    return rpcResult(id ?? null, {});
  }
  return rpcError(id ?? null, -32601, "unknown_method:" + method);
}

let pending = 0;
let closing = false;
function maybeExit() {
  if (closing && pending === 0) process.exit(0);
}
const rl = readline.createInterface({ input: process.stdin, terminal: false });
rl.on("line", async (line) => {
  const trimmed = String(line).trim();
  if (!trimmed) return;
  pending += 1;
  rl.pause();
  try {
    let msg;
    try {
      msg = JSON.parse(trimmed);
    } catch (err) {
      process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id: null, error: { message: String(err) } }) + "\n");
      return;
    }
    const reply = await handleRpc(msg);
    if (reply) process.stdout.write(JSON.stringify(reply) + "\n");
  } finally {
    pending -= 1;
    rl.resume();
    maybeExit();
  }
});
rl.on("close", () => {
  closing = true;
  maybeExit();
});
process.stderr.write("mcp-server stdio ready name=" + SERVER_NAME + "\n");
